    @version.setter
    def version(self, value: Optional[str]) -> None:
        self._raw.version = value

    @property
    def pipeline(self) -> Any:
        return self._raw.pipeline

    @pipeline.setter
    def pipeline(self, value: Any) -> None:
        self._raw.pipeline = value

    async def aclose(self) -> None:
        await self._raw.aclose()

    async def __aenter__(self) -> "AsyncClient":
        return self

    async def __aexit__(self, *exc: Any) -> None:
        await self.aclose()

    async def connect_device(self, args: ConnectDeviceArgs) -> str:
        """## Connect a device to a terminal

        Connect a device to a terminal instance. If the terminal has no device bound,
        this will bind the provided `device_id` and generate a fresh API key token
        (prefixed with `reservepay_`). If the terminal is already bound to the same
        `device_id`, the previous key is revoked and a new one is issued.

        If the terminal is bound to a different device, an `ALREADY_CONNECTED` error
        is returned.

        If the terminal is disabled, `NOT_ENABLED` is returned.

        If the terminal has no installation linked, `NOT_CONFIGURED` is returned.

        Raises:
            webfunction.BadRequestError: code "ALREADY_CONNECTED" - The terminal is connected to another device.
            webfunction.BadRequestError: code "INVALID_CHALLENGE" - The challenge is missing or does not match the terminal's current challenge.
            webfunction.BadRequestError: code "NOT_FOUND" - Merchant or terminal could not be found.
            webfunction.BadRequestError: code "NOT_ENABLED" - The terminal exists but is disabled; enable it before connecting a device.
            webfunction.BadRequestError: code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation first.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("connect-device", raw_args)
        return cast(str, result)

    async def connect_device_by_code(self, args: ConnectDeviceByCodeArgs) -> str:
        """## Connect a device with a temporary challenge

        Connect a device to the terminal that owns the given 8-digit temporary challenge.
        The code must be unexpired. On success the device is bound, a fresh API key token
        (prefixed with `reservepay_`) is returned, and the temporary challenge is cleared.

        If the terminal is already bound to a different device, `ALREADY_CONNECTED` is returned.
        If it is bound to the same device, the previous key is revoked and a new one is issued.

        If the terminal is disabled, `NOT_ENABLED` is returned.

        If the terminal has no installation linked, `NOT_CONFIGURED` is returned.

        Raises:
            webfunction.BadRequestError: code "ALREADY_CONNECTED" - The terminal is connected to another device.
            webfunction.BadRequestError: code "INVALID_CHALLENGE" - The code is unknown or has expired.
            webfunction.BadRequestError: code "NOT_ENABLED" - The terminal exists but is disabled; enable it before connecting a device.
            webfunction.BadRequestError: code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation first.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("connect-device-by-code", raw_args)
        return cast(str, result)

    async def retrieve_installation_settings(self, args: RetrieveInstallationSettingsArgs) -> RetrieveInstallationSettingsResult:
        """## Retrieve the installation settings

        Returns settings and configuration for the installation linked to the terminal
        (payment methods, UI options, etc.), after verifying the bound device.

        The terminal must be connected via `connect-device` and must have an installation
        configured on the merchant terminal record.

        Raises:
            webfunction.BadRequestError: code "NOT_FOUND" - The merchant or terminal could not be found, or no device is bound to the terminal.
            webfunction.BadRequestError: code "UNRECOGNIZED_DEVICE" - The device_id does not match the one bound to the terminal.
            webfunction.BadRequestError: code "NOT_ENABLED" - The terminal exists but is disabled.
            webfunction.BadRequestError: code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation to the terminal first.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("retrieve-installation-settings", raw_args)
        return RetrieveInstallationSettingsResult._from_dict(result)

    async def verify_connection(self, args: VerifyConnectionArgs) -> str:
        """## Verify connection

        Verifies the connection between a physical device and a terminal.

        Returns one of:
        - `CONNECTED` when the provided device is bound to the terminal
        - `RESET_CONNECTION` when no device is bound (erase keys/PIN and call `connect-device`)

        If no device is bound, you should call the [connect-device](/api/terminals/connect-device) endpoint.

        Errors:
        - `UNRECOGNIZED_DEVICE` if another device is currently bound
        - `NOT_FOUND` if the merchant or terminal cannot be found
        - `NOT_ENABLED` if the terminal is disabled
        - `NOT_CONFIGURED` if the terminal has no installation linked

        Raises:
            webfunction.BadRequestError: code "UNRECOGNIZED_DEVICE" - The device_id does not match the one bound to the terminal.
            webfunction.BadRequestError: code "NOT_FOUND" - Merchant or terminal could not be found.
            webfunction.BadRequestError: code "NOT_ENABLED" - The terminal exists but is disabled.
            webfunction.BadRequestError: code "NOT_CONFIGURED" - The terminal has no installation linked; assign an installation first.
            webfunction.UnexpectedStatusCodeError: if the server responds with a non-200/400 status
            webfunction.JsonParseError: if the response body isn't valid JSON
        """
        raw_args = _to_args_dict(args)
        result = await self._raw.call("verify-connection", raw_args)
        return cast(str, result)

